import data from './floorball.json'

// Generated by scripts/fetch-floorball.mjs from legendarnaliga.sk.
// Do not edit floorball.json by hand: it is refreshed on every build and weekly by CI.

export interface PlayerLine {
  number: number | null
  name: string
  goals: number
  assists: number
  points: number
  /** Penalty minutes */
  pim: number
}

export interface Match {
  /** Local time, "2026-11-28T15:30" */
  date: string
  opponent: string
  home: boolean
  /** "6:3" from Dynamo's point of view, null when not played yet */
  score: string | null
  result: 'W' | 'L' | 'D' | null
  /** Jurgo was on the match sheet */
  played: boolean
  events?: { goals: number, assists: number, penalties: number }
}

export interface FloorballSeason {
  id: string
  season: string
  league: string
  club: string
  me: { number: number | null, games: number, goals: number, assists: number, points: number, pim: number }
  team: { played: number, won: number, lost: number, goalsFor: number, goalsAgainst: number }
  players: PlayerLine[]
  matches: Match[]
}

export interface StandingRow {
  position: number
  team: string
  played: number
  won: number
  wonOt: number
  lostOt: number
  lost: number
  score: string
  points: number
}

export interface FloorballData {
  updatedAt: string
  source: string
  team: { name: string, url: string }
  player: { name: string, url: string }
  standings: { season: string, group: string | null, rows: StandingRow[] } | null
  /** Newest first */
  seasons: FloorballSeason[]
}

export const floorball = data as FloorballData

export const isMe = (name: string) => name.toLowerCase().includes('paluš')
export const isMyTeam = (name: string) => name.toLowerCase() === floorball.team.name.toLowerCase()
